//! Deterministic seed generator/verifier for the `archive_repair` fuzz target.
//!
//! By default this test verifies that the committed seeds in
//! `fuzz/seeds/archive_repair/` match the generated bytes.  Set
//! `SAR_WRITE_FUZZ_SEEDS=1` to (re)write them:
//!
//! ```text
//! SAR_WRITE_FUZZ_SEEDS=1 cargo test -p sar-archive --test archive_repair_fuzz_seeds
//! ```
//!
//! The seed layouts are documented in `fuzz/fuzz_targets/archive_repair.rs`.

use std::{fs, path::PathBuf};

use sar_archive::recovery::{
    ErasureInput, ErasureRange, inspect_recovery_metadata, plan_archive_repair, repair_archive,
};
use sar_core::{
    GlobalFlags, ResourceLimits,
    format::{
        CentralDictionary, Footer, GlobalHeader, write_central_dictionary, write_footer,
        write_global_header,
    },
    tlv::Tlv,
};
use sar_fec::{FecCodec, FecOptions, RsCodec, XorCodec};

fn seed_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../fuzz/seeds/archive_repair")
}

fn archive(protected_len: usize, xor: bool) -> Vec<u8> {
    let flags = GlobalFlags::HAS_GLOBAL_EC | GlobalFlags::OPT_PRESENT;
    let mut a = write_global_header(&GlobalHeader {
        version: 0x01,
        flags,
        kms: None,
    })
    .expect("test setup");
    let data_len = protected_len + 8 - a.len();
    a.extend((0..data_len).map(|i| u8::try_from((i * 31 + i / 251) % 251).expect("test setup")));
    let cd_offset = a.len() as u64;
    let protected = a[8..].to_vec();
    let (type_id, value) = if xor {
        let v = XorCodec::new(4, 0)
            .expect("test setup")
            .encode_recovery(&protected, FecOptions)
            .expect("test setup");
        (0x14, v.data)
    } else {
        let v = RsCodec::new(4, 2, 256)
            .expect("test setup")
            .encode_recovery(&protected, FecOptions)
            .expect("test setup");
        (0x11, v.data)
    };
    let cd = CentralDictionary {
        version: 0x01,
        file_count: 0,
        global_crc32: None,
        metadata: vec![Tlv { type_id, value }],
        offsets: Vec::new(),
    };
    a.extend_from_slice(&write_central_dictionary(&cd, flags).expect("test setup"));
    a.extend_from_slice(&write_footer(Footer { cd_offset }));
    a
}

struct Structured {
    codec: u8,
    a: u8,
    b: u8,
    c: u8,
    protected: u16,
    selector: u8,
    limit: u32,
    tamper: u8,
    ranges: Vec<[u8; 4]>,
}

impl Structured {
    fn new(codec: u8, a: u8, b: u8, c: u8, protected: u16) -> Self {
        Self {
            codec,
            a,
            b,
            c,
            protected,
            selector: 1,
            limit: 0,
            tamper: 0,
            ranges: Vec::new(),
        }
    }
    /// `blocks` is the erased block count (the target decodes `1 + byte % 4`).
    fn range(mut self, start: u8, blocks: u8, jitter: u8, fill: u8) -> Self {
        self.ranges.push([start, blocks - 1, jitter, fill]);
        self
    }
    fn bytes(&self) -> Vec<u8> {
        let mut v = vec![0, self.codec, self.a, self.b, self.c];
        v.extend_from_slice(&self.protected.to_le_bytes());
        v.push(self.selector);
        v.extend_from_slice(&self.limit.to_le_bytes());
        v.push(self.tamper);
        v.push(u8::try_from(self.ranges.len()).expect("test setup"));
        for r in &self.ranges {
            v.extend_from_slice(r);
        }
        v
    }
}

fn raw(tamper: u8, selector: u8, limit: u32, ranges: &[(u64, u64)], archive: &[u8]) -> Vec<u8> {
    let mut v = vec![
        1,
        tamper,
        u8::try_from(ranges.len()).expect("test setup"),
        selector,
    ];
    v.extend_from_slice(&limit.to_le_bytes());
    for (o, l) in ranges {
        v.extend_from_slice(&o.to_le_bytes());
        v.extend_from_slice(&l.to_le_bytes());
    }
    v.extend_from_slice(archive);
    v
}

fn seeds() -> Vec<(&'static str, Vec<u8>)> {
    // Protected length is `64 + protected`, i.e. 4096 / 2048 / 16064 bytes.
    let xor = |p| Structured::new(0, 3, 0, 0, p);
    let rs = |p| Structured::new(1, 3, 1, 2, p);

    let xor_arch = archive(2048, true);
    let rs_arch = archive(2048, false);
    let mut truncated = xor_arch.clone();
    truncated.truncate(truncated.len() - 20);
    let mut bad_footer = rs_arch.clone();
    let n = bad_footer.len();
    bad_footer[n - 8] ^= 0xFF;
    let valid_xor = [(8 + 256, 256), (8 + 256 * 5, 256)];
    let valid_rs = [(8 + 256, 512)];

    vec![
        (
            "structured_xor_two_erasures.bin",
            xor(4032).range(1, 1, 4, 0xEE).range(6, 1, 4, 0x55).bytes(),
        ),
        (
            "structured_rs_two_symbols.bin",
            rs(1984).range(0, 2, 4, 0xAA).bytes(),
        ),
        ("structured_no_erasures.bin", xor(4032).bytes()),
        (
            "structured_xor_stripe_overfull.bin",
            xor(4032).range(0, 4, 4, 0x11).bytes(),
        ),
        (
            "structured_xor_unaligned.bin",
            xor(4032).range(2, 1, 0, 0x22).bytes(),
        ),
        (
            "structured_xor_before_range.bin",
            xor(4032).range(2, 1, 1, 0x33).bytes(),
        ),
        (
            "structured_xor_overlong.bin",
            xor(4032).range(14, 1, 2, 0x44).bytes(),
        ),
        (
            "structured_zero_length.bin",
            xor(4032).range(3, 1, 3, 0x66).bytes(),
        ),
        (
            "structured_rs_overlapping.bin",
            rs(1984)
                .range(0, 1, 4, 1)
                .range(0, 2, 4, 2)
                .range(1, 1, 4, 3)
                .bytes(),
        ),
        (
            "structured_xor_wide_stripe.bin",
            Structured::new(0, 254, 3, 0, 16_000)
                .range(2, 1, 4, 0x77)
                .bytes(),
        ),
        (
            "structured_tampered_plan.bin",
            Structured {
                tamper: 3,
                ..xor(4032).range(1, 1, 4, 0xEE)
            }
            .bytes(),
        ),
        (
            "structured_tiny_limit.bin",
            Structured {
                selector: 0,
                limit: 1000,
                ..xor(4032).range(1, 1, 4, 0xEE)
            }
            .bytes(),
        ),
        ("raw_xor_valid.bin", raw(0, 1, 0, &valid_xor, &xor_arch)),
        ("raw_rs_valid.bin", raw(0, 1, 0, &valid_rs, &rs_arch)),
        (
            "raw_xor_tampered_algo.bin",
            raw(7, 1, 0, &valid_xor, &xor_arch),
        ),
        (
            "raw_rs_tight_limit.bin",
            raw(0, 2, 40_000, &valid_rs, &rs_arch),
        ),
        (
            "raw_truncated_archive.bin",
            raw(0, 1, 0, &valid_xor, &truncated),
        ),
        (
            "raw_corrupt_footer.bin",
            raw(0, 1, 0, &valid_rs, &bad_footer),
        ),
        (
            "raw_overflow_ranges.bin",
            raw(0, 1, 0, &[(u64::MAX, 2), (8, u64::MAX)], &xor_arch),
        ),
        (
            "raw_range_before_protected.bin",
            raw(0, 1, 0, &[(0, 256), (4, 256)], &xor_arch),
        ),
        (
            "raw_huge_range.bin",
            raw(0, 1, 0, &[(8, 1 << 40)], &xor_arch),
        ),
        ("raw_header_only.bin", vec![1]),
    ]
}

#[test]
fn archive_repair_seeds_match_generator() {
    let dir = seed_dir();
    let write = std::env::var_os("SAR_WRITE_FUZZ_SEEDS").is_some();
    if write {
        fs::create_dir_all(&dir).expect("test setup");
    }
    for (name, bytes) in seeds() {
        let path = dir.join(name);
        if write {
            fs::write(&path, &bytes).expect("test setup");
        } else {
            let committed = fs::read(&path).unwrap_or_else(|e| panic!("{name}: {e}"));
            assert_eq!(committed, bytes, "{name} is stale; regenerate seeds");
        }
    }
}

/// The valid raw seeds must reach real planning and repair rather than being
/// rejected during parsing.
#[test]
fn valid_raw_seed_archives_plan_and_repair() {
    let limits = ResourceLimits::unlimited();
    for (xor, ranges) in [
        (true, vec![(8 + 256, 256u64), (8 + 256 * 5, 256)]),
        (false, vec![(8 + 256, 512)]),
    ] {
        let a = archive(2048, xor);
        assert!(
            inspect_recovery_metadata(&a, &limits)
                .expect("test setup")
                .repair_possible
        );
        let plan = plan_archive_repair(
            &a,
            ErasureInput {
                entries: Vec::new(),
                archive_ranges: ranges
                    .iter()
                    .map(|&(offset, length)| ErasureRange { offset, length })
                    .collect(),
            },
            &limits,
        )
        .expect("test setup");
        let (repaired, _) = repair_archive(&a, &plan, &limits).expect("test setup");
        assert_eq!(repaired, a);
    }
}
